input.command:
cd /tmp/probe-container && cat > probe.sh <<'EOF'
#!/bin/bash
# usage: probe.sh <blocksize>
bs=$1
hb(){ printf 'hello' | /workspace/executable -z -T2 --check=crc32 --block-size=$bs "$@" 2>/dev/null | od -A n -t x1 -j 12 -N 1 | tr -d ' \n'; }
declare -A base=( [A]=9 [B]=11 [C]=12 [D]=14 )
lo=0; hi=100
for k in A B C D; do
  case $k in
    A) v=$(hb --lzma2=preset=6);;
    B) v=$(hb --x86 --lzma2=preset=6);;
    C) v=$(hb --delta=dist=1 --lzma2=preset=6);;
    D) v=$(hb --delta=dist=1 --x86 --lzma2=preset=6);;
  esac
  [ -z "$v" ] && { echo "$k FAILED"; continue; }
  hs=$(( (0x$v + 1) * 4 ))
  b=${base[$k]}
  # b + s <= hs  and  b + s > hs-4
  l=$(( hs - 3 - b )); h=$(( hs - b ))
  [ $l -gt $lo ] && lo=$l
  [ $h -lt $hi ] && hi=$h
done
echo "bs=$bs  cs+us in [$lo,$hi]"
EOF
chmod +x probe.sh && ./probe.sh 128 && ./probe.sh 1 && ./probe.sh 1000000

