for k in range(1,10):
    lim=1<<(7*k)
    # want 65539*m+96 <= lim-1 < 65539*m+99  => lim-99 <= 65539m <= lim-97
    for m in range((lim-100)//65539, (lim-90)//65539+2):
        v=65539*m
        if lim-99<=v<=lim-97: print('k',k,'m',m,'u',m*65536,'lim',lim)
" ; echo "search done"
